// Finds the bricks currently overlapping the ball and gives the ball a single
// per-face bounce off them. Returns the array of collided (now dead) bricks.
// All collided bricks are destroyed, but the velocity is flipped only ONCE:
// a ball spanning a seam between two bricks must not bounce twice (the two
// flips would cancel and the ball would sail through).
export function bounceBall(ball, bricks) {
  const hit = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (!collides(ball, brick)) continue;
    hit.push(brick);
    brick.alive = false;
  }
  if (hit.length === 0) return hit;

  // Compute the bounce from the FIRST collided brick (a representative of the
  // whole seam) so the deflection is applied exactly once.
  const brick = hit[0];

  // Penetration depth on each side (how far the ball overlaps past the face).
  const overlapLeft = ball.x + ball.r - brick.x;      // ball sticking in from the left
  const overlapRight = brick.x + brick.w - (ball.x - ball.r); // from the right
  const overlapTop = ball.y + ball.r - brick.y;       // from the top
  const overlapBottom = brick.y + brick.h - (ball.y - ball.r); // from the bottom

  // The face with the SMALLEST overlap is the one that was actually struck.
  const minX = Math.min(overlapLeft, overlapRight);
  const minY = Math.min(overlapTop, overlapBottom);

  if (minX < minY) {
    // side hit
    if (overlapLeft < overlapRight) {
      ball.x = brick.x - ball.r; // push out the left side
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r; // push out the right side
      ball.vx = Math.abs(ball.vx);
    }
  } else if (minY < minX) {
    // top/bottom hit
    if (overlapTop < overlapBottom) {
      ball.y = brick.y - ball.r; // entered from the top, push up
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r; // entered from the bottom, push down
      ball.vy = Math.abs(ball.vy);
    }
  } else {
    // corner: equal penetrations -> flip both components
    // push out along both axes
    if (overlapLeft <= overlapRight) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
    if (overlapTop <= overlapBottom) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  }

  return hit;
}
```

