```js
// Resolves the ball against every brick it currently overlaps and returns the
// list of bricks hit (which are marked dead). The ball is given a single
// per-face bounce: the axis with the smaller penetration is the face struck —
// a top/bottom hit flips `vy`, a side hit flips `vx`, and a corner (equal
// penetrations) flips both. After each flip the ball is pushed back outside the
// brick so it cannot re-collide on the next frame (sticky bounce).
//
// Bricks are resolved from the ball's ORIGINAL position in one pass and the
// velocity is deflected exactly once: because the ball (14 px wide) is wider
// than the 8 px grid gap, it can overlap two bricks in a seam at once. Two
// flips of the same axis would cancel and let the ball sail straight through.
export function brickHit(ball, bricks) {
  // Collect every brick overlapping the ball (before any repositioning).
  const hit = [];
  for (const brick of bricks) {
    if (brick.alive && collides(ball, brick)) {
      brick.alive = false;
      hit.push(brick);
    }
  }
  if (hit.length === 0) return hit;

  // The first brick is a representative of the whole seam; bounce once off it.
  const brick = hit[0];

  const overlapLeft = ball.x + ball.r - brick.x;
  const overlapRight = brick.x + brick.w - (ball.x - ball.r);
  const overlapTop = ball.y + ball.r - brick.y;
  const overlapBottom = brick.y + brick.h - (ball.y - ball.r);

  const minX = Math.min(overlapLeft, overlapRight);
  const minY = Math.min(overlapTop, overlapBottom);

  const fromLeft = overlapLeft <= overlapRight;
  const fromTop = overlapTop <= overlapBottom;

  if (minX < minY) {
    // Side hit: flip vx only.
    if (fromLeft) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  } else if (minY < minX) {
    // Top/bottom hit: flip vy only.
    if (fromTop) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  } else {
    // Corner hit: equal penetrations -> flip both axes and push out both ways.
    if (fromLeft) {
      ball.x = brick.x - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
    if (fromTop) {
      ball.y = brick.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  }

  return hit;
}
```

