// --- Rendering (DOM): still scans every brick per frame (debt #2) ----------

// Main render loop. Brick collision is resolved up front by the pure
// `brickHit`, then the surviving bricks are drawn. Rendering stays in this
// function, but the collision logic no longer is entangled with it.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: resolve collisions + scoring first (brickHit bounces the ball and
  // destroys the bricks it touched), then draw the survivors.
  const hit = brickHit(state.ball, state.bricks);
  for (const brick of hit) {
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

